WITH with_windows AS (SELECT *, MIN(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_budget, COUNT(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_budget, AVG(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_budget, ROW_NUMBER() OVER (PARTITION BY dept_name, location ORDER BY budget ASC, id ASC) AS event_seq FROM departments) SELECT CASE WHEN budget >= 3305000 THEN 'PREMIUM' ELSE 'STANDARD' END AS budget_tier, CASE WHEN last3_count_budget >= 13 THEN 'LARGE' ELSE 'SMALL' END AS last3_count_budget_tier, ROUND(AVG(budget), 2) AS avg_budget, SORT_ARRAY(COLLECT_SET(dept_name)) AS dept_name_list, ROUND(SUM(last3_avg_budget) / NULLIF(COUNT(CASE WHEN location = 'Tokyo' THEN 1 END), 0), 2) AS last3_avg_budget_per_tokyo, COUNT(*) FILTER (WHERE dept_name = 'Sales') AS sales_rows, COUNT(*) AS cnt FROM with_windows GROUP BY budget_tier, last3_count_budget_tier
